class Solution { long long range(long long start,long long count){return count*(2*start+count-1)/2;}public:long long minimalKSum(vector<int>& nums,int k){sort(nums.begin(),nums.end());long long current=1,answer=0,remaining=k;for(int value:nums){if(value<current)continue;long long take=min(remaining,(long long)value-current);answer+=range(current,take);remaining-=take;if(!remaining)return answer;current=(long long)value+1;}return answer+range(current,remaining);} };
